export const patternRoutes: PatternRoute[] = [
  { slug: 'component-composition/children-composition', title: 'children 조합', englishTitle: 'Children Composition', category: '컴포넌트 조합', summary: '공통 레이아웃은 컴포넌트가 맡고 실제 내용은 children으로 주입합니다.', whyMatters: 'wrapper 컴포넌트가 내부 콘텐츠 타입을 직접 알기 시작하면 variant prop이 쌓이고, 결국 레이아웃 컴포넌트가 여러 도메인 정책을 모두 아는 거대한 조건문이 됩니다. children으로 책임을 나누면 껍데기와 내용의 변경 이유가 분리됩니다.', keyPoints: ['wrapper는 테두리, 간격, 제목만 책임진다', '내용 종류가 늘어도 wrapper 파일을 수정하지 않는다', 'JSX 구조만 봐도 화면 구성이 이해된다'], Component: Example0, BadCase: BadCase0 },
  { slug: 'component-composition/compound-component', title: '합성 컴포넌트', englishTitle: 'Compound Component', category: '컴포넌트 조합', summary: 'Root, Trigger, Panel처럼 협력하는 하위 컴포넌트를 하나의 API로 묶습니다.', whyMatters: 'Tabs처럼 여러 하위 요소가 같은 상태를 공유해야 하는 UI를 단일 items 배열로 처리하면, 나중에 badge·disabled·아이콘 같은 요구사항이 생길 때마다 컴포넌트 내부를 수정해야 합니다. Compound component는 상태 연결은 내부가 맡고 JSX 구조는 호출부가 자유롭게 조합하게 합니다.', keyPoints: ['Root가 Context로 상태를 제공하고 Trigger/Panel이 읽는다', '호출부에서 하위 요소 배치를 직접 조합할 수 있다', '접근성 속성(role, aria-*)은 라이브러리가 내부에서 보장한다', 'Root 밖에서 하위 컴포넌트를 쓰면 명확한 에러가 난다'], Component: Example1, BadCase: BadCase1 },
  { slug: 'component-composition/slot-pattern', title: '슬롯 패턴', englishTitle: 'Slot Pattern', category: '컴포넌트 조합', summary: 'header, actions, footer처럼 이름 있는 영역을 호출부가 채우게 합니다.', whyMatters: '단일 children은 구역 의미가 모호합니다. Page 레이아웃에 제목, 액션 버튼, 본문이 한 children으로 들어오면 컴포넌트 내부에서 순서나 타입을 강제할 수밖에 없습니다. slot prop은 각 영역에 이름을 부여해 의도를 명확히 합니다.', keyPoints: ['header, footer, actions처럼 영역 이름이 명시된다', '호출부가 어떤 영역에 무엇을 넣는지 JSX에서 바로 읽힌다', '특정 slot을 생략하면 해당 영역이 렌더되지 않아도 된다'], Component: Example2, BadCase: BadCase2 },
  { slug: 'component-composition/headless-component', title: '헤드리스 컴포넌트', englishTitle: 'Headless Component', category: '컴포넌트 조합', summary: '상태와 동작만 제공하고 마크업과 스타일은 호출부가 결정합니다.', whyMatters: '디자인 시스템이 없는 환경에서 Combobox 같은 복잡한 상호작용을 처음부터 만들면, 동작과 UI가 하나의 컴포넌트에 묶여 다른 디자인에 재사용하기 어렵습니다. Headless는 동작을 훅이나 렌더리스 컴포넌트로 분리해 어떤 마크업에도 결합할 수 있게 합니다.', keyPoints: ['같은 동작 로직을 완전히 다른 시각 디자인에 재사용한다', 'Radix UI, Headless UI 같은 라이브러리가 이 방식으로 설계됐다', '복잡한 접근성 로직을 중앙화하고 마크업은 자유롭게 남긴다'], Component: Example3, BadCase: BadCase3 },
  { slug: 'component-composition/controlled-uncontrolled', title: '제어/비제어 컴포넌트', englishTitle: 'Controlled / Uncontrolled', category: '컴포넌트 조합', summary: '내부 상태 사용과 외부 상태 제어를 모두 지원합니다.', whyMatters: '라이브러리 컴포넌트를 만들 때 controlled만 지원하면 간단한 사용에도 상태 관리가 강제되고, uncontrolled만 지원하면 외부에서 값을 제어할 수 없습니다. 두 모드를 동시에 지원하면 사용자가 필요에 따라 선택할 수 있습니다.', keyPoints: ['value prop이 없으면 내부 상태로 동작한다', 'value + onChange가 있으면 외부가 상태를 소유한다', 'defaultValue로 초기값을 주되 이후 제어는 내부에 맡길 수 있다'], Component: Example4, BadCase: BadCase4 },
  { slug: 'component-composition/render-props', title: '렌더 프롭스', englishTitle: 'Render Props', category: '컴포넌트 조합', summary: '상태와 동작을 함수 인자로 넘기고 렌더링은 호출부가 담당합니다.', whyMatters: 'Custom hook이 주류가 됐지만 render props는 JSX 트리 안에서 상태를 공유해야 할 때 여전히 유효합니다. 특히 특정 컨텍스트의 상태를 자식 컴포넌트가 아닌 render 함수로 소비해야 할 때 명확합니다.', keyPoints: ['children을 함수로 받아 (state) => JSX 형태로 쓴다', '상태를 JSX 트리 안에서 직접 소비할 수 있다', 'hooks 이전에 로직 재사용의 주요 패턴이었고 지금도 특정 상황에 적합하다'], Component: Example5, BadCase: BadCase5 },
  { slug: 'component-composition/provider-pattern', title: 'Provider 패턴', englishTitle: 'Provider Pattern', category: '컴포넌트 조합', summary: '공유 관심사를 Context Provider로 공급하고 필요한 하위 컴포넌트만 읽게 합니다.', whyMatters: 'props drilling이 3단계 이상 깊어지거나 완전히 무관한 컴포넌트들이 같은 값을 필요로 할 때, Provider로 공통 조상에 상태를 두고 소비자만 context를 읽게 하면 중간 컴포넌트에 prop이 퍼지지 않습니다.', keyPoints: ['theme, auth, locale 같은 앱 전역 관심사에 적합하다', '소비자 컴포넌트만 리렌더되고 중간 컴포넌트는 무관하다', 'context value가 자주 바뀌면 소비 범위를 나눠 최적화해야 한다'], Component: Example6, BadCase: BadCase6 },
  { slug: 'component-composition/polymorphic-component', title: '다형성 컴포넌트', englishTitle: 'Polymorphic Component', category: '컴포넌트 조합', summary: '공통 스타일을 유지하면서 as prop으로 실제 HTML element를 바꿉니다.', whyMatters: 'Button 컴포넌트를 링크로도 써야 할 때, ButtonLink, ButtonAnchor처럼 별도 컴포넌트를 만들면 동일한 스타일 코드가 중복됩니다. as prop 하나로 렌더 element를 바꾸면 스타일은 유지하면서 시맨틱을 바꿀 수 있습니다.', keyPoints: ['as="a"면 링크, as="button"이면 버튼으로 렌더된다', '공통 className, variant, size 로직을 한 곳에서 관리한다', 'TypeScript로 as에 따라 props 타입이 자동으로 좁혀진다'], Component: Example7, BadCase: BadCase7 },
  { slug: 'component-composition/props-getter', title: 'props getter 패턴', englishTitle: 'Props Getter', category: '컴포넌트 조합', summary: '접근성, 이벤트, 상태 props를 안전하게 합성해 호출부에 제공합니다.', whyMatters: 'Headless 훅이 onClick을 제공하고 호출부도 onClick이 있으면 한쪽이 덮어씁니다. props getter는 라이브러리의 필수 핸들러와 사용자 핸들러를 안전하게 병합해 둘 다 실행되게 합니다.', keyPoints: ['getButtonProps()가 aria-*, onClick, role을 한번에 반환한다', '사용자 커스텀 handler와 라이브러리 handler가 모두 실행된다', 'Downshift, react-table 등이 이 패턴으로 API를 제공한다'], Component: Example8, BadCase: BadCase8 },
  { slug: 'component-composition/container-presenter', title: '컨테이너/프리젠터', englishTitle: 'Container / Presenter', category: '컴포넌트 조합', summary: '데이터 준비와 화면 표현의 책임을 분리합니다.', whyMatters: '한 컴포넌트가 API 호출, 상태 관리, 이벤트 처리, JSX 렌더링을 모두 하면 테스트하기 어렵고 재사용도 불가능합니다. Container는 데이터를 준비하고 Presenter는 props만 받아 렌더링하면 각각 독립적으로 테스트할 수 있습니다.', keyPoints: ['Presenter는 순수 함수처럼 props → JSX만 담당한다', 'Container를 교체해도 Presenter UI는 그대로 재사용된다', 'hooks가 나온 뒤 Container 역할을 custom hook이 대체하는 경우가 많다'], Component: Example9, BadCase: BadCase9 },
  { slug: 'state-management/local-state-first', title: '가까운 상태 우선', englishTitle: 'Local State First', category: '상태 관리', summary: '상태는 가장 작은 소유 범위에서 시작하고 필요할 때만 올립니다.', whyMatters: '처음부터 모든 상태를 전역 store에 넣으면 단순한 토글 하나도 전역 액션이 됩니다. 상태를 가장 필요한 컴포넌트 가까이에 두면 의존관계가 줄고, 해당 컴포넌트를 삭제할 때 상태도 함께 사라집니다.', keyPoints: ['전역화는 항상 마지막 수단이다', '지역 상태는 컴포넌트와 함께 태어나고 함께 사라진다', '여러 형제가 공유할 때만 부모로 올린다'], Component: Example10, BadCase: BadCase10 },
  { slug: 'state-management/state-colocation', title: '상태 위치 맞추기', englishTitle: 'State Colocation', category: '상태 관리', summary: '상태를 실제로 읽고 바꾸는 코드 가까이에 둡니다.', whyMatters: '상태가 실제 사용 위치보다 위에 있으면, 그 사이의 모든 컴포넌트가 불필요한 리렌더를 겪습니다. 상태를 내려보내거나 올리는 게 아니라 "정확히 필요한 위치"에 배치하는 것이 핵심입니다.', keyPoints: ['상태 소유자가 변경되면 그 하위 트리만 리렌더된다', '너무 높이 올린 상태는 불필요한 props와 리렌더를 만든다', 'Colocation을 적용하면 컴포넌트 독립성이 높아진다'], Component: Example11, BadCase: BadCase11 },
  { slug: 'state-management/lifting-state-up', title: '상태 끌어올리기', englishTitle: 'Lifting State Up', category: '상태 관리', summary: '여러 형제가 같은 상태를 필요로 할 때 가장 가까운 공통 부모로 올립니다.', whyMatters: '두 형제 컴포넌트가 같은 데이터를 필요로 할 때 각자 useState를 만들면 동기화 문제가 생깁니다. 공통 부모로 상태를 올리면 단일 출처(single source of truth)가 생깁니다.', keyPoints: ['형제 간 동기화 문제를 설계 차원에서 해결한다', '공통 부모가 유일한 상태 소유자가 된다', '올릴 때 불필요한 리렌더가 늘면 Context나 상태 분리를 검토한다'], Component: Example12, BadCase: BadCase12 },
  { slug: 'state-management/derived-state', title: '파생 상태', englishTitle: 'Derived State', category: '상태 관리', summary: '저장하지 않아도 되는 값은 기존 상태에서 계산합니다.', whyMatters: '장바구니 합계를 items 배열과 별도 total state로 관리하면, items가 바뀔 때 total도 동기화하는 effect가 필요합니다. 이 effect는 버그의 온상입니다. total을 items에서 계산하면 동기화 문제 자체가 없어집니다.', keyPoints: ['저장 state 수를 줄이면 동기화 버그 가능성이 줄어든다', '계산 비용이 크면 useMemo로 캐시한다', 'effect로 state를 동기화하는 코드가 보이면 derived state를 의심한다'], Component: Example13, BadCase: BadCase13 },
  { slug: 'state-management/reducer-pattern', title: 'reducer 패턴', englishTitle: 'Reducer Pattern', category: '상태 관리', summary: '복잡한 상태 전이를 action과 reducer로 한 곳에 모읍니다.', whyMatters: '상태 필드가 많고 여러 이벤트가 여러 필드를 함께 바꾸면, 흩어진 setState들이 어떤 이벤트에 어떤 상태 변화를 만드는지 추적하기 어렵습니다. reducer는 "이 액션 → 이 상태"를 한 함수 안에서 명확히 보여줍니다.', keyPoints: ['상태 전이 로직을 컴포넌트 밖에서 순수하게 테스트할 수 있다', 'action type으로 이벤트 의도를 명시한다', 'undo/redo, 이력 추적을 구현하기 좋다'], Component: Example14, BadCase: BadCase14 },
  { slug: 'state-management/url-state', title: 'URL 상태', englishTitle: 'URL State', category: '상태 관리', summary: '공유와 복원이 필요한 필터, 검색어, 페이지 정보를 URL에 둡니다.', whyMatters: '검색 필터를 useState에 두면 페이지를 새로고침하거나 링크를 공유할 때 필터 상태가 사라집니다. URL에 두면 링크 하나로 정확한 상태를 공유·북마크·복원할 수 있습니다.', keyPoints: ['새로고침해도 상태가 유지된다', 'URL을 복사해 동료와 공유할 수 있다', '뒤로가기/앞으로가기가 자연스럽게 동작한다'], Component: Example15, BadCase: BadCase15 },
  { slug: 'state-management/server-state-vs-client-state', title: '서버 상태와 클라이언트 상태', englishTitle: 'Server State vs Client State', category: '상태 관리', summary: '원격 데이터와 화면 제어 상태의 소유권을 분리합니다.', whyMatters: '서버에서 받은 유저 목록과 "어떤 유저가 선택됐는가"를 같은 store에 섞으면, 서버 데이터를 다시 fetch할 때 UI 상태까지 초기화되거나 반대로 캐시 무효화가 복잡해집니다. 두 종류의 상태는 성격이 달라 분리해야 합니다.', keyPoints: ['서버 상태: 원격 데이터, stale/fresh, 캐시 전략이 필요하다', '클라이언트 상태: 선택, 열림/닫힘, 필터 같은 UI 제어 값이다', 'TanStack Query는 서버 상태를, Zustand는 클라이언트 상태를 잘 다룬다'], Component: Example16, BadCase: BadCase16 },
  { slug: 'state-management/optimistic-ui', title: '낙관적 UI', englishTitle: 'Optimistic UI', category: '상태 관리', summary: '성공 가능성이 높은 액션은 먼저 UI를 바꾸고 실패 시 되돌립니다.', whyMatters: '"좋아요" 버튼을 누를 때마다 서버 응답을 기다리면 인터랙션이 500ms씩 지연됩니다. 성공을 낙관적으로 가정하고 즉시 UI를 바꾸면 서버 왕복 지연을 체감하지 못하고, 실패 시에만 되돌리면 됩니다.', keyPoints: ['성공률이 높고 롤백이 간단한 액션에 적합하다', '롤백 로직을 미리 준비해두어야 한다', '낙관적 업데이트 중임을 사용자에게 시각적으로 알리는 것이 좋다'], Component: Example17, BadCase: BadCase17 },
  { slug: 'state-management/state-machine', title: '상태 머신', englishTitle: 'State Machine', category: '상태 관리', summary: '허용 가능한 상태와 전이만 명시해 복잡한 UI 흐름을 안정화합니다.', whyMatters: 'isLoading, isSuccess, isError, isRetrying를 동시에 boolean으로 관리하면 isLoading && isError가 동시에 true가 되는 불가능한 상태가 생깁니다. 상태 머신은 한 번에 하나의 상태만 허용해 이런 버그를 원천적으로 막습니다.', keyPoints: ['불가능한 상태 조합이 타입 수준에서 차단된다', '허용된 전이만 가능하므로 예상치 못한 상태 변화가 없다', 'XState, 단순 union type 모두 같은 원리를 적용한다'], Component: Example18, BadCase: BadCase18 },
  { slug: 'state-management/external-store', title: '외부 store 연결', englishTitle: 'External Store', category: '상태 관리', summary: 'React 밖의 store를 useSyncExternalStore로 안전하게 연결합니다.', whyMatters: '브라우저 store(localStorage, IndexedDB)나 서드파티 상태 라이브러리를 React 컴포넌트와 연결할 때 useEffect + setState를 쓰면 Concurrent Mode에서 tearing(찢김) 현상이 생길 수 있습니다. useSyncExternalStore는 이를 안전하게 처리합니다.', keyPoints: ['React 외부 상태를 Concurrent Mode에서 안전하게 구독한다', 'SSR을 위한 getServerSnapshot도 지원한다', 'Zustand, Valtio 같은 라이브러리가 내부적으로 이 훅을 사용한다'], Component: Example19, BadCase: BadCase19 },
  { slug: 'hooks/custom-hook-boundary', title: '커스텀 훅 경계', englishTitle: 'Custom Hook Boundary', category: '훅과 로직 재사용', summary: '도메인 로직을 custom hook으로 캡슐화하고 컴포넌트는 렌더링에 집중합니다.', whyMatters: '데이터 페칭, 이벤트 구독, 복잡한 상태 로직이 컴포넌트 안에 있으면 컴포넌트가 비대해지고 로직을 다른 화면에서 재사용하기 어렵습니다. custom hook으로 추출하면 로직과 UI의 변경 이유가 분리됩니다.', keyPoints: ['컴포넌트는 훅에서 가져온 값과 함수만 쓴다', '같은 로직을 여러 컴포넌트에서 재사용할 수 있다', '훅은 컴포넌트 없이 단위 테스트가 가능하다'], Component: Example20, BadCase: BadCase20 },
  { slug: 'hooks/use-controllable-state', title: '제어 가능 상태 훅', englishTitle: 'useControllableState', category: '훅과 로직 재사용', summary: 'controlled/uncontrolled 상태 소유권 분기를 훅 하나로 표준화합니다.', whyMatters: '컴포넌트 라이브러리를 만들 때 controlled/uncontrolled를 각 컴포넌트마다 if문으로 처리하면 중복이 많고 실수가 생깁니다. useControllableState 하나로 이 분기를 중앙화하면 일관성이 보장됩니다.', keyPoints: ['value prop 유무로 자동으로 controlled/uncontrolled를 판단한다', 'onChange는 항상 일관되게 호출된다', 'Radix UI, Ark UI 등 컴포넌트 라이브러리가 이 패턴을 사용한다'], Component: Example21, BadCase: BadCase21 },
  { slug: 'hooks/use-disclosure', title: '열림/닫힘 훅', englishTitle: 'useDisclosure', category: '훅과 로직 재사용', summary: 'modal, drawer, dropdown의 open/close/toggle 상태를 공통 인터페이스로 다룹니다.', whyMatters: 'Modal, Drawer, Popover마다 isOpen, setIsOpen을 선언하고 open/close 함수를 만들면 동일한 코드가 반복됩니다. useDisclosure 하나로 이 인터페이스를 표준화하면 코드가 줄고 팀 내 일관성이 생깁니다.', keyPoints: ['{ isOpen, open, close, toggle } 인터페이스를 표준화한다', '여러 모달이 있어도 각각 useDisclosure를 쓰면 명확하다', 'Chakra UI의 useDisclosure가 이 패턴의 대표적인 예다'], Component: Example22, BadCase: BadCase22 },
  { slug: 'hooks/use-debounce', title: 'debounce 훅', englishTitle: 'useDebounce', category: '훅과 로직 재사용', summary: '연속 입력을 일정 시간 멈춘 뒤 마지막 값만 반영합니다.', whyMatters: '검색 input에서 키를 누를 때마다 API를 호출하면 "react"를 입력하는 동안 r, re, rea, reac, react 5번의 요청이 나갑니다. debounce는 마지막 입력 후 일정 시간 기다린 뒤 한 번만 요청해 서버 부하를 줄입니다.', keyPoints: ['입력이 멈춘 후 delay ms 뒤에 값이 안정된다', '검색, 자동저장, 크기 측정 등에 활용된다', 'throttle과 달리 마지막 값에 집중한다'], Component: Example23, BadCase: BadCase23 },
  { slug: 'hooks/use-throttle', title: 'throttle 훅', englishTitle: 'useThrottle', category: '훅과 로직 재사용', summary: '반복 이벤트의 실행 빈도를 일정 간격으로 제한합니다.', whyMatters: 'scroll, mousemove, resize 이벤트는 초당 수십~수백 번 발생합니다. 이 이벤트마다 DOM 계산이나 상태 업데이트를 하면 프레임 드랍이 생깁니다. throttle은 최대 실행 빈도를 제한해 성능을 보호합니다.', keyPoints: ['일정 간격마다 최대 한 번 실행된다', '스크롤 이벤트, 마우스 이동 추적에 적합하다', 'debounce와 달리 중간 값도 정기적으로 반영된다'], Component: Example24, BadCase: BadCase24 },
  { slug: 'hooks/use-previous', title: '이전 값 훅', englishTitle: 'usePrevious', category: '훅과 로직 재사용', summary: '직전 렌더의 값을 ref에 보관해 현재 값과 비교합니다.', whyMatters: '값이 증가했는지 감소했는지, 특정 prop이 바뀌었는지 비교하려면 이전 값이 필요합니다. useEffect의 deps로는 "변화 감지"를 하기 어렵고, usePrevious는 이 목적에 정확히 맞습니다.', keyPoints: ['ref에 보관하므로 값 변경이 리렌더를 유발하지 않는다', '현재 값과 이전 값을 렌더 중에 동시에 읽을 수 있다', '애니메이션 방향 결정, 변화 강조 표시에 사용된다'], Component: Example25, BadCase: BadCase25 },
  { slug: 'hooks/use-outside-click', title: '바깥 클릭 감지 훅', englishTitle: 'useOutsideClick', category: '훅과 로직 재사용', summary: '특정 영역 바깥 pointer 이벤트를 감지합니다.', whyMatters: 'Dropdown, Popover, Combobox는 바깥을 클릭하면 닫혀야 합니다. 이 로직을 컴포넌트마다 직접 작성하면 이벤트 위임, 버블링, ref 관리가 반복됩니다. useOutsideClick으로 추출하면 재사용과 테스트가 쉬워집니다.', keyPoints: ['ref로 영역을 지정하고 바깥 클릭 시 콜백을 실행한다', 'pointerdown을 쓰면 터치 이벤트도 처리된다', '마운트/언마운트 시 자동으로 구독/해제한다'], Component: Example26, BadCase: BadCase26 },
  { slug: 'hooks/use-event-listener', title: '이벤트 구독 훅', englishTitle: 'useEventListener', category: '훅과 로직 재사용', summary: 'DOM 이벤트 구독과 cleanup을 훅 경계 안에 둡니다.', whyMatters: 'useEffect로 addEventListener를 하면 cleanup에서 removeEventListener를 빠뜨리기 쉽습니다. useEventListener로 추출하면 구독과 해제가 항상 함께 다뤄지고 의도치 않은 메모리 누수를 방지합니다.', keyPoints: ['effect 안에서 add/remove를 한 쌍으로 처리한다', 'target이 바뀌면 이전 구독을 자동 해제하고 새로 구독한다', 'window, document, ref 모두 target으로 받을 수 있다'], Component: Example27, BadCase: BadCase27 },
  { slug: 'hooks/use-async', title: '비동기 상태 훅', englishTitle: 'useAsync', category: '훅과 로직 재사용', summary: '비동기 작업의 loading/data/error 상태를 공통 모델로 다룹니다.', whyMatters: '컴포넌트마다 isLoading, error, data를 따로 선언하면 같은 패턴이 반복되고 각 경우 처리를 빠뜨리기 쉽습니다. useAsync 하나로 이 모델을 표준화하면 비동기 처리가 일관됩니다.', keyPoints: ['idle → loading → success/error 상태 머신을 내장한다', '언마운트 후 setState를 막아 경고를 방지한다', 'TanStack Query가 없는 환경에서 직접 만들기 좋다'], Component: Example28, BadCase: BadCase28 },
  { slug: 'hooks/use-mounted', title: '마운트 여부 훅', englishTitle: 'useMounted', category: '훅과 로직 재사용', summary: '컴포넌트 마운트 여부를 비동기 흐름에서 확인합니다.', whyMatters: '비동기 요청이 완료됐을 때 컴포넌트가 이미 언마운트됐다면 setState를 해도 아무것도 없고 React 경고가 납니다. isMounted 체크로 이를 방지합니다. AbortController가 더 좋지만 isMounted 체크도 알아야 할 패턴입니다.', keyPoints: ['useRef로 마운트 여부를 추적한다', '비동기 콜백 실행 전 isMounted()를 확인한다', 'AbortController로 요청 자체를 취소하는 게 더 권장되지만 함께 쓸 수 있다'], Component: Example29, BadCase: BadCase29 },
  { slug: 'hooks/query-command-hook', title: '조회/명령 훅 분리', englishTitle: 'Query / Command Hook', category: '훅과 로직 재사용', summary: '읽기 훅과 쓰기 명령 훅을 분리합니다.', whyMatters: '읽기(query)와 쓰기(mutation)를 한 훅에 모으면 컴포넌트가 이 훅 하나만 있어도 데이터를 바꿀 권한을 갖습니다. 분리하면 각 컴포넌트에 정확히 필요한 권한만 줄 수 있고 테스트도 독립적입니다.', keyPoints: ['useUsers()는 조회만, useDeleteUser()는 명령만 담당한다', '읽기 전용 컴포넌트에 mutation 훅을 넣지 않아도 된다', 'TanStack Query의 useQuery/useMutation 분리와 같은 원리다'], Component: Example30, BadCase: BadCase30 },
  { slug: 'hooks/hook-composition', title: '훅 조합', englishTitle: 'Hook Composition', category: '훅과 로직 재사용', summary: '작은 훅을 조합해 더 큰 도메인 훅을 만듭니다.', whyMatters: '하나의 거대한 훅이 검색어 debounce, URL 동기화, API 호출, 에러 처리를 모두 하면 재사용과 테스트가 어렵습니다. 작은 훅을 조합하면 각 부분을 독립적으로 교체하거나 테스트할 수 있습니다.', keyPoints: ['useDebounce + useAsync + useUrlState → useProductSearch', '각 훅은 단일 책임을 갖고 독립적으로 테스트 가능하다', '조합의 결과물인 도메인 훅이 컴포넌트의 인터페이스가 된다'], Component: Example31, BadCase: BadCase31 },
  { slug: 'async-api/query-hook-pattern', title: '조회 훅 패턴', englishTitle: 'Query Hook Pattern', category: '비동기와 API 상태', summary: '조회 요청을 전용 훅으로 감싸 화면에서 요청 세부사항을 숨깁니다.', whyMatters: '컴포넌트 안에 fetch URL, 파라미터, 에러 처리가 직접 있으면 API가 바뀔 때 모든 컴포넌트를 수정해야 합니다. query hook으로 감싸면 API 계약 변경이 훅 하나를 수정하는 것으로 끝납니다.', keyPoints: ['컴포넌트는 "어떻게 가져오는지" 몰라도 된다', 'loading/error/data를 훅이 반환한다', 'API endpoint 변경이 훅 파일 하나로 격리된다'], Component: Example32, BadCase: BadCase32 },
  { slug: 'async-api/mutation-hook-pattern', title: 'mutation 훅 패턴', englishTitle: 'Mutation Hook Pattern', category: '비동기와 API 상태', summary: '쓰기 요청을 명령형 mutation 훅으로 분리합니다.', whyMatters: '폼 제출 핸들러에 fetch 로직, 에러 처리, 상태 업데이트가 모두 들어 있으면 컴포넌트가 비대해지고 재사용이 어렵습니다. mutation hook으로 분리하면 컴포넌트는 "무엇을 제출할지"만 결정합니다.', keyPoints: ['mutate() 함수를 컴포넌트에 제공한다', 'isPending, isError, isSuccess 상태를 반환한다', 'TanStack Query useMutation이 이 패턴의 표준 구현이다'], Component: Example33, BadCase: BadCase33 },
  { slug: 'async-api/cache-invalidation', title: '캐시 무효화', englishTitle: 'Cache Invalidation', category: '비동기와 API 상태', summary: '쓰기 이후 영향을 받는 조회 캐시를 명시적으로 stale 처리합니다.', whyMatters: '상품을 삭제했는데 목록 화면이 여전히 삭제된 상품을 보여주면 사용자가 혼란스럽습니다. mutation 후 관련 query cache를 무효화하면 다음 조회 시 최신 데이터를 가져옵니다.', keyPoints: ['mutation onSuccess에서 관련 queryKey를 invalidate한다', '무효화된 쿼리는 다음 마운트/포커스 시 자동으로 재요청된다', '어떤 쿼리를 무효화할지 명시적으로 선언하면 사이드이펙트가 추적된다'], Component: Example34, BadCase: BadCase34 },
  { slug: 'async-api/optimistic-update', title: '낙관적 업데이트', englishTitle: 'Optimistic Update', category: '비동기와 API 상태', summary: '서버 응답 전에 캐시를 먼저 갱신하고 실패 시 롤백합니다.', whyMatters: '할 일 완료 체크처럼 빠른 피드백이 중요한 UI에서 서버 응답을 기다리면 인터랙션이 느리게 느껴집니다. cache를 먼저 갱신하면 응답 전에도 UI가 반영되고, 실패 시 이전 캐시로 복원합니다.', keyPoints: ['onMutate에서 캐시를 먼저 업데이트하고 이전 값을 저장한다', 'onError에서 이전 값으로 캐시를 복원한다', 'onSettled에서 서버 최신 상태와 동기화한다'], Component: Example35, BadCase: BadCase35 },
  { slug: 'async-api/pagination', title: '페이지네이션', englishTitle: 'Pagination', category: '비동기와 API 상태', summary: '페이지 번호와 pageSize 기준으로 목록 조회 상태를 관리합니다.', whyMatters: '모든 데이터를 한 번에 가져오면 초기 로딩이 오래 걸리고 서버 부하가 큽니다. 페이지 단위로 나누면 첫 화면이 빠르고 사용자가 필요한 만큼만 데이터를 불러옵니다.', keyPoints: ['현재 page와 pageSize를 상태로 관리한다', 'page가 바뀔 때 새 데이터를 요청한다', '전체 개수(total)로 페이지 수를 계산한다'], Component: Example36, BadCase: BadCase36 },
  { slug: 'async-api/infinite-query', title: '무한 조회', englishTitle: 'Infinite Query', category: '비동기와 API 상태', summary: '커서나 페이지 묶음을 누적해 무한 스크롤 목록을 만듭니다.', whyMatters: 'SNS 피드처럼 "더 보기"나 무한 스크롤을 구현할 때 이전 데이터를 유지하면서 새 페이지를 누적해야 합니다. 일반 페이지네이션은 페이지 전환 시 이전 데이터를 버립니다.', keyPoints: ['페이지 데이터를 배열로 누적 관리한다', '마지막 페이지의 커서로 다음 요청을 보낸다', 'IntersectionObserver로 스크롤 끝 감지를 자동화한다'], Component: Example37, BadCase: BadCase37 },
  { slug: 'async-api/api-adapter', title: 'API 어댑터', englishTitle: 'API Adapter', category: '비동기와 API 상태', summary: '서버 응답 구조를 React UI 모델로 변환합니다.', whyMatters: '서버 응답의 snake_case, 중첩 구조, 불필요한 필드가 컴포넌트 props까지 흘러들어오면 서버 스키마 변경이 UI 전체에 영향을 줍니다. adapter에서 한 번 변환하면 UI는 서버 구조와 독립됩니다.', keyPoints: ['서버 타입과 UI 타입을 분리한다', 'adapter 함수는 순수함수로 테스트하기 쉽다', '서버 스키마가 바뀌어도 adapter만 수정하면 된다'], Component: Example38, BadCase: BadCase38 },
  { slug: 'async-api/request-status-model', title: '요청 상태 모델', englishTitle: 'Request Status Model', category: '비동기와 API 상태', summary: '요청 상태를 여러 boolean 대신 명시적 union으로 표현합니다.', whyMatters: 'isLoading, isSuccess, isError를 각각 boolean으로 가지면 isLoading && isSuccess가 동시에 true인 불가능한 상태가 생깁니다. union type으로 모델링하면 한 시점에 하나의 상태만 가능합니다.', keyPoints: ["'idle' | 'loading' | 'success' | 'error' union이 불가능한 상태를 차단한다", '타입스크립트 exhaustive check로 모든 케이스를 처리했는지 확인할 수 있다', '렌더링 분기가 switch/if로 명확해진다'], Component: Example39, BadCase: BadCase39 },
  { slug: 'async-api/error-boundary', title: '에러 경계', englishTitle: 'Error Boundary', category: '비동기와 API 상태', summary: '렌더링 중 발생한 오류를 화면 경계에서 잡아 대체 UI를 보여줍니다.', whyMatters: '컴포넌트에서 throw된 에러가 잡히지 않으면 앱 전체가 빈 화면이 됩니다. ErrorBoundary는 해당 구역의 에러를 격리해 나머지 화면은 정상 동작하게 하고 대체 UI를 보여줍니다.', keyPoints: ['class 컴포넌트로만 구현 가능하지만 래퍼로 쉽게 쓸 수 있다', '에러를 잡는 범위를 granular하게 나눌 수 있다', 'react-error-boundary 라이브러리가 많이 사용된다'], Component: Example40, BadCase: BadCase40 },
  { slug: 'async-api/suspense-boundary', title: 'Suspense 경계', englishTitle: 'Suspense Boundary', category: '비동기와 API 상태', summary: '비동기 로딩 경계를 선언적으로 나누고 fallback을 제공합니다.', whyMatters: 'isLoading을 모든 컴포넌트에서 직접 처리하면 로딩 분기가 JSX 곳곳에 흩어집니다. Suspense는 "이 영역이 준비되면 보여준다"는 의도를 JSX 구조로 선언해 로딩 관심사를 상위로 올립니다.', keyPoints: ['로딩 상태 분기를 JSX가 아닌 Suspense 경계로 처리한다', 'ErrorBoundary와 함께 로딩/에러 경계를 선언한다', 'React 18 Concurrent 기능과 함께 활용도가 높아졌다'], Component: Example41, BadCase: BadCase41 },
  { slug: 'forms/controlled-form', title: '제어 폼', englishTitle: 'Controlled Form', category: '폼과 검증', summary: '입력 값을 React state로 직접 제어합니다.', whyMatters: '입력 값이 state에 있으면 실시간 유효성 검사, 조건부 필드 표시, 입력 포맷팅을 자연스럽게 할 수 있습니다. 단 필드가 많아질수록 렌더가 잦아지므로 React Hook Form 같은 라이브러리를 검토해야 합니다.', keyPoints: ['value + onChange로 입력을 완전히 제어한다', '실시간 유효성 검사와 조건부 렌더링이 쉽다', '필드가 많으면 렌더 최적화를 고려한다'], Component: Example42, BadCase: BadCase42 },
  { slug: 'forms/uncontrolled-form', title: '비제어 폼', englishTitle: 'Uncontrolled Form', category: '폼과 검증', summary: 'DOM이 입력 값을 보관하고 제출 시점에 값을 읽습니다.', whyMatters: '단순한 로그인 폼처럼 제출 시점에만 값이 필요하고 중간에 값을 읽을 필요가 없다면, 불필요한 리렌더를 피하기 위해 uncontrolled form이 더 적합합니다.', keyPoints: ['ref.current.value로 제출 시점에만 값을 읽는다', '타이핑 중에 리렌더가 발생하지 않는다', 'React Hook Form이 내부적으로 uncontrolled 방식을 사용한다'], Component: Example43, BadCase: BadCase43 },
  { slug: 'forms/field-level-validation', title: '필드 단위 검증', englishTitle: 'Field Level Validation', category: '폼과 검증', summary: '각 필드의 규칙과 오류 메시지를 필드 가까이에 둡니다.', whyMatters: '검증 규칙이 폼 submit 핸들러에만 있으면 어떤 필드가 어떤 규칙을 갖는지 찾기 어렵습니다. 필드 레벨로 분리하면 규칙과 UI가 함께 있어 유지보수가 쉽습니다.', keyPoints: ['각 필드가 자신의 validate 함수를 갖는다', '포커스를 잃을 때(onBlur) 해당 필드만 검증한다', 'React Hook Form register의 validate 옵션이 이 방식이다'], Component: Example44, BadCase: BadCase44 },
  { slug: 'forms/form-level-validation', title: '폼 단위 검증', englishTitle: 'Form Level Validation', category: '폼과 검증', summary: '여러 필드의 조합을 폼 단위에서 검증합니다.', whyMatters: '"비밀번호 확인"처럼 두 필드를 비교하는 규칙은 필드 레벨에서 처리하기 어렵습니다. Zod schema나 폼 레벨 validate 함수에서 전체 값을 받아 교차 검증합니다.', keyPoints: ['교차 필드 규칙(비밀번호 일치, 날짜 범위)을 처리한다', 'Zod/Yup schema를 폼 레벨에서 적용한다', '필드 레벨 검증과 폼 레벨 검증을 병행할 수 있다'], Component: Example45, BadCase: BadCase45 },
  { slug: 'forms/server-error-mapping', title: '서버 오류 매핑', englishTitle: 'Server Error Mapping', category: '폼과 검증', summary: '서버 오류를 필드 오류와 폼 전체 오류로 변환합니다.', whyMatters: '이메일 중복처럼 클라이언트에서 미리 알 수 없는 오류는 서버가 응답해야 합니다. 이 응답을 폼 필드 옆에 정확히 표시하지 않으면 사용자가 무엇이 잘못됐는지 모릅니다.', keyPoints: ['서버 응답의 field 이름으로 각 필드 에러를 setError 한다', '전역 오류는 별도 영역에 표시한다', '422 Unprocessable Entity 응답의 errors 배열을 매핑하는 게 일반적이다'], Component: Example46, BadCase: BadCase46 },
  { slug: 'forms/dirty-state', title: '변경 여부 상태', englishTitle: 'Dirty State', category: '폼과 검증', summary: '초기값과 현재값을 비교해 변경 여부를 추적합니다.', whyMatters: '"저장되지 않은 변경사항이 있습니다" 경고나 저장 버튼 활성화를 위해 폼이 변경됐는지 알아야 합니다. 초기값과 현재값을 비교하면 됩니다.', keyPoints: ['초기값(defaultValues)을 별도로 보관한다', '현재값과 깊은 비교(deep equal)로 dirty 여부를 계산한다', 'React Hook Form의 formState.isDirty가 이 패턴을 제공한다'], Component: Example47, BadCase: BadCase47 },
  { slug: 'forms/submit-lock', title: '제출 잠금', englishTitle: 'Submit Lock', category: '폼과 검증', summary: '제출 중 같은 액션이 다시 실행되지 않도록 잠급니다.', whyMatters: '결제 버튼을 빠르게 두 번 누르면 중복 결제가 발생할 수 있습니다. isSubmitting 상태로 버튼을 disabled 처리하면 처음 제출이 완료되기 전까지 다시 제출할 수 없습니다.', keyPoints: ['제출 시작 시 isSubmitting=true, 완료/실패 시 false로 되돌린다', '버튼을 disabled 처리하고 loading 표시를 보여준다', '서버 요청이 아닌 UI에서도 중복 방지가 필요하다'], Component: Example48, BadCase: BadCase48 },
  { slug: 'forms/dependent-fields', title: '의존 필드', englishTitle: 'Dependent Fields', category: '폼과 검증', summary: '한 필드의 값이 다른 필드의 선택지나 유효성을 결정합니다.', whyMatters: '"국가"를 선택하면 "도시" 목록이 바뀌는 종속 관계를 구현할 때, 두 필드가 독립적이면 국가 변경 시 도시 선택이 유효하지 않은 값을 유지할 수 있습니다. 의존 관계를 명시적으로 처리해야 합니다.', keyPoints: ['부모 필드 값이 바뀌면 자식 필드를 리셋한다', '자식 필드의 options을 부모 값으로 계산한다', 'watch()로 다른 필드 값을 관찰해 조건부 렌더링에 쓴다'], Component: Example49, BadCase: BadCase49 },
  { slug: 'forms/dynamic-fields', title: '동적 필드', englishTitle: 'Dynamic Fields', category: '폼과 검증', summary: '반복 가능한 필드 배열을 안정적인 id와 함께 추가/삭제합니다.', whyMatters: '팀원 이메일을 여러 개 입력하는 폼에서 index를 key로 쓰면, 중간 항목을 삭제할 때 입력값이 꼬입니다. 각 항목에 고유 id를 부여하면 추가/삭제 시 상태가 안정됩니다.', keyPoints: ['항목마다 고유 id를 생성해 key로 쓴다', '추가는 배열 append, 삭제는 id 기준 filter로 처리한다', 'React Hook Form useFieldArray가 이 패턴을 제공한다'], Component: Example50, BadCase: BadCase50 },
  { slug: 'forms/multi-step-form', title: '단계형 폼', englishTitle: 'Multi Step Form', category: '폼과 검증', summary: '긴 폼을 단계별 상태와 검증으로 나눕니다.', whyMatters: '회원가입처럼 입력 항목이 많은 폼을 한 페이지에 모으면 사용자가 부담을 느낍니다. 단계로 나누면 각 단계를 검증하고 넘어가므로 오류를 일찍 발견하고 완료율이 높아집니다.', keyPoints: ['현재 step 인덱스로 어떤 화면을 보여줄지 결정한다', '각 step에서 해당 필드만 검증한다', '전체 데이터는 상위에서 관리하고 단계별로 나눠 보여준다'], Component: Example51, BadCase: BadCase51 },
  { slug: 'ui-state/loading-empty-error', title: '로딩/빈 상태/에러', englishTitle: 'Loading / Empty / Error', category: 'UI 상태 표현', summary: '목록 화면의 loading, empty, error, success 상태를 일관되게 분기합니다.', whyMatters: '상태 분기를 빠뜨리면 로딩 중에 빈 목록이 보이거나 에러 시 아무것도 안 보입니다. 4가지 상태를 명시적으로 처리하면 어떤 상황에서도 적절한 UI를 보여줄 수 있습니다.', keyPoints: ['loading, empty, error, data 4가지 상태를 모두 처리한다', '각 상태는 다음 행동을 안내해야 한다', '상태 순서: loading 먼저, 그 다음 error, 마지막에 empty/data'], Component: Example52, BadCase: BadCase52 },
  { slug: 'ui-state/skeleton-vs-spinner', title: '스켈레톤 vs 스피너', englishTitle: 'Skeleton vs Spinner', category: 'UI 상태 표현', summary: '대기 시간과 레이아웃 예측 가능성에 따라 skeleton과 spinner를 선택합니다.', whyMatters: 'skeleton은 "여기에 무언가 올 것이다"라는 예측을 줘 체감 대기 시간을 줄이고 레이아웃 시프트를 방지합니다. 반면 전체 페이지 전환처럼 최종 레이아웃을 예측할 수 없으면 spinner가 맞습니다.', keyPoints: ['skeleton: 내용 레이아웃이 예측 가능한 카드, 목록에 사용한다', 'spinner: 전체 페이지 로딩, 레이아웃 불확실 시 사용한다', 'skeleton이 있으면 사용자가 레이아웃 시프트를 덜 경험한다'], Component: Example53, BadCase: BadCase53 },
  { slug: 'ui-state/toast-vs-inline-error', title: '토스트 vs 인라인 오류', englishTitle: 'Toast vs Inline Error', category: 'UI 상태 표현', summary: '오류의 복구 위치에 따라 toast와 inline 메시지를 선택합니다.', whyMatters: '폼 필드 오류를 toast로 보내면 사용자가 어떤 필드를 고쳐야 하는지 모릅니다. 반대로 전역 시스템 오류를 모든 폼 필드 아래 표시하면 연관성이 없습니다. 오류 위치와 복구 행동이 맞아야 합니다.', keyPoints: ['inline: 특정 필드/영역과 직접 연관된 오류', 'toast: 어디서든 볼 수 있는 일시적 알림, 성공 메시지', '치명적 오류는 페이지 전체 에러 상태로 표현한다'], Component: Example54, BadCase: BadCase54 },
  { slug: 'ui-state/confirm-dialog', title: '확인 다이얼로그', englishTitle: 'Confirm Dialog', category: 'UI 상태 표현', summary: '파괴적 행동 전에 명확한 확인 단계를 둡니다.', whyMatters: '삭제, 영구 취소처럼 되돌릴 수 없는 행동을 클릭 한 번에 실행하면 실수가 발생합니다. 확인 다이얼로그는 의도를 다시 확인하고 실수를 방지하는 안전장치입니다.', keyPoints: ['파괴적 행동에 명확한 경고 문구를 쓴다', '확인 버튼을 위험 색상으로 강조한다', '취소가 기본 포커스를 가져야 실수 방지에 효과적이다'], Component: Example55, BadCase: BadCase55 },
  { slug: 'ui-state/pending-state', title: '처리 중 상태', englishTitle: 'Pending State', category: 'UI 상태 표현', summary: '사용자 액션이 처리 중임을 버튼과 관련 영역에 표시합니다.', whyMatters: '버튼을 누른 뒤 화면이 아무 반응이 없으면 사용자는 "제출이 됐나?" 하고 다시 누릅니다. 처리 중 상태를 즉시 보여주면 불안감을 줄이고 중복 제출을 방지합니다.', keyPoints: ['버튼을 disabled + 로딩 스피너로 즉각 피드백을 준다', '처리 중인 영역을 시각적으로 구분한다', '완료 후 성공/실패 상태로 전환한다'], Component: Example56, BadCase: BadCase56 },
  { slug: 'ui-state/disabled-state', title: '비활성 상태', englishTitle: 'Disabled State', category: 'UI 상태 표현', summary: '액션이 불가능한 상태와 이유를 명확히 표현합니다.', whyMatters: '버튼이 왜 비활성 상태인지 모르면 사용자가 좌절합니다. 비활성 버튼에 tooltip이나 도움말을 붙여 "무엇을 해야 활성화되는지" 알려주면 UX가 크게 개선됩니다.', keyPoints: ['단순 disabled 속성만으론 이유를 전달하지 못한다', 'tooltip이나 helper text로 비활성 이유를 명시한다', 'aria-disabled와 함께 스크린 리더도 고려한다'], Component: Example57, BadCase: BadCase57 },
  { slug: 'ui-state/empty-state', title: '빈 상태', englishTitle: 'Empty State', category: 'UI 상태 표현', summary: '빈 결과를 막다른 화면이 아니라 다음 행동으로 연결합니다.', whyMatters: '"결과가 없습니다" 텍스트만 있으면 사용자는 다음에 무엇을 해야 할지 모릅니다. 일러스트, 설명, 액션 버튼을 함께 제공하면 빈 상태가 전환점이 됩니다.', keyPoints: ['검색 결과 없음: 다른 검색어 시도, 필터 초기화 CTA를 제공한다', '데이터 없음: 첫 항목 생성 CTA를 제공한다', '이미지 + 제목 + 설명 + 버튼 구조가 효과적이다'], Component: Example58, BadCase: BadCase58 },
  { slug: 'ui-state/error-state', title: '에러 상태', englishTitle: 'Error State', category: 'UI 상태 표현', summary: '복구 가능한 오류를 명확한 메시지와 액션으로 보여줍니다.', whyMatters: '오류 코드만 보여주거나 아무것도 안 보여주면 사용자가 무엇을 해야 하는지 모릅니다. 무슨 문제인지, 어떻게 해결할 수 있는지를 명확히 하면 사용자 이탈을 줄일 수 있습니다.', keyPoints: ['다시 시도 버튼으로 복구 경로를 제공한다', '오류 코드보다 사용자 언어로 설명한다', '오류 유형에 따라 retry/refresh/go-home 등 적절한 액션을 제공한다'], Component: Example59, BadCase: BadCase59 },
  { slug: 'performance-rendering/memoization-boundary', title: '메모이제이션 경계', englishTitle: 'Memoization Boundary', category: '렌더링 성능', summary: 'memoization을 비용이 큰 하위 트리의 경계에 둡니다.', whyMatters: '부모가 리렌더될 때마다 자식도 리렌더됩니다. 렌더 비용이 큰 자식을 React.memo로 감싸면 props가 바뀌지 않는 한 리렌더를 건너뜁니다. 단, 모든 컴포넌트에 적용하면 memo 비교 비용이 오히려 더 커집니다.', keyPoints: ['비용이 큰 자식에만 적용하고 기본 컴포넌트에는 불필요하다', 'props에 인라인 객체/함수가 있으면 memo가 효과없다', '측정 먼저, 최적화는 병목 확인 후에 한다'], Component: Example60, BadCase: BadCase60 },
  { slug: 'performance-rendering/usememo-usecallback', title: 'useMemo/useCallback 기준', englishTitle: 'useMemo / useCallback', category: '렌더링 성능', summary: '값과 함수 identity 안정성이 필요한 지점에만 사용합니다.', whyMatters: 'useMemo와 useCallback은 비용을 줄이는 것처럼 보이지만 캐시 관리와 deps 비교 비용이 있습니다. "모든 곳에 useCallback"은 오히려 코드를 복잡하게만 합니다. 정말 필요한 두 가지 상황: 비싼 계산, 안정적 참조가 필요할 때입니다.', keyPoints: ['useCallback: memo된 자식에 넘기는 함수나 useEffect deps', 'useMemo: 렌더마다 새로 계산하기 비싼 값', '대부분의 경우 없어도 앱은 잘 동작한다'], Component: Example61, BadCase: BadCase61 },
  { slug: 'performance-rendering/component-splitting', title: '컴포넌트 분리', englishTitle: 'Component Splitting', category: '렌더링 성능', summary: '변경 빈도가 다른 영역을 컴포넌트로 분리합니다.', whyMatters: '타이머처럼 자주 바뀌는 부분과 정적인 콘텐츠가 같은 컴포넌트에 있으면, 타이머가 바뀔 때마다 정적 콘텐츠도 리렌더됩니다. 분리하면 바뀌는 부분만 리렌더되고 나머지는 건드리지 않습니다.', keyPoints: ['변경 빈도가 다른 UI를 별도 컴포넌트로 추출한다', 'memo 없이도 리렌더 범위를 좁힐 수 있다', '상태를 소유하는 컴포넌트 범위가 리렌더 범위다'], Component: Example62, BadCase: BadCase62 },
  { slug: 'performance-rendering/list-rendering', title: '목록 렌더링', englishTitle: 'List Rendering', category: '렌더링 성능', summary: '큰 목록의 렌더 비용을 줄이고 key 안정성을 보장합니다.', whyMatters: '10,000개 항목을 한 번에 렌더하면 초기 렌더가 수초 걸립니다. 가상화(virtualization)는 보이는 항목만 렌더해 DOM 노드 수를 일정하게 유지합니다. 안정적인 key는 불필요한 DOM 재생성을 막습니다.', keyPoints: ['1000개 이상 목록에는 가상화(react-window, TanStack Virtual)를 검토한다', '각 항목의 고유 id를 key로 쓴다', '항목이 React.memo면 key 안정성과 props 안정성 모두 중요하다'], Component: Example63, BadCase: BadCase63 },
  { slug: 'performance-rendering/lazy-loading', title: '지연 로딩', englishTitle: 'Lazy Loading', category: '렌더링 성능', summary: '초기 화면에 필요 없는 코드를 늦게 불러옵니다.', whyMatters: '모달, 관리자 패널, 세부 화면처럼 첫 화면에서 보이지 않는 컴포넌트가 초기 번들에 포함되면 LCP가 늦어집니다. React.lazy로 코드 스플리팅하면 초기 번들 크기를 줄여 첫 로딩이 빨라집니다.', keyPoints: ['React.lazy + Suspense로 컴포넌트 수준에서 분리한다', '라우트 단위로 적용하면 효과가 크다', 'Suspense fallback으로 로딩 중 화면을 보여준다'], Component: Example64, BadCase: BadCase64 },
  { slug: 'performance-rendering/expensive-calculation', title: '비싼 계산 처리', englishTitle: 'Expensive Calculation', category: '렌더링 성능', summary: '무거운 계산을 필요한 시점에만 실행하거나 캐시합니다.', whyMatters: '대용량 데이터 정렬, 복잡한 필터링을 매 렌더마다 실행하면 타이핑 한 번에도 수십 ms가 걸릴 수 있습니다. useMemo로 의존 값이 바뀔 때만 재계산하면 불필요한 계산을 건너뜁니다.', keyPoints: ['useMemo의 deps가 바뀔 때만 재계산한다', '실제로 비싼지 console.time으로 먼저 측정한다', '단순 배열 filter, 짧은 계산에 useMemo는 오버엔지니어링이다'], Component: Example65, BadCase: BadCase65 },
  { slug: 'performance-rendering/render-tracking', title: '렌더 추적', englishTitle: 'Render Tracking', category: '렌더링 성능', summary: '렌더 횟수와 원인을 관찰해 최적화 대상을 찾습니다.', whyMatters: '"느리다"는 느낌만으로 useCallback을 추가하는 것은 측정 없는 최적화입니다. 실제로 어떤 컴포넌트가 몇 번 렌더되는지 측정한 뒤 병목이 확인된 곳만 최적화해야 합니다.', keyPoints: ['useRef로 렌더 횟수를 세는 useRenderCount 훅을 만든다', 'React DevTools Profiler로 렌더 원인을 분석한다', '측정 없는 최적화는 복잡도만 올린다'], Component: Example66, BadCase: BadCase66 },
  { slug: 'performance-rendering/context-optimization', title: 'Context 최적화', englishTitle: 'Context Optimization', category: '렌더링 성능', summary: 'Context value와 Provider 범위를 쪼개 불필요한 렌더를 줄입니다.', whyMatters: 'Context value가 바뀌면 useContext를 호출하는 모든 컴포넌트가 리렌더됩니다. 자주 바뀌는 값과 거의 안 바뀌는 값을 같은 Context에 넣으면 불필요한 리렌더가 퍼집니다.', keyPoints: ['자주 바뀌는 값과 안정적인 값을 별도 Context로 분리한다', '상태와 dispatch를 다른 Context에 분리하는 방법도 효과적이다', 'Context 대신 Zustand 같은 selector 기반 store가 더 효율적일 수 있다'], Component: Example67, BadCase: BadCase67 },
  { slug: 'anti-patterns/use-effect-for-derived-state', title: '파생 상태를 effect로 만들기', englishTitle: 'useEffect For Derived State', category: '안티패턴', summary: '계산 가능한 값을 effect와 state로 중복 저장하는 문제를 피합니다.', whyMatters: 'items 배열에서 계산되는 filteredItems를 state로 저장하면, items가 바뀔 때 동기화하는 useEffect가 필요합니다. 이 effect는 한 렌더 뒤에 실행되어 flickering을 유발하고 동기화 버그의 온상이 됩니다.', keyPoints: ['렌더 중 계산 가능한 값은 state로 저장하지 않는다', 'useMemo로 충분하고, 렌더 중 동기적으로 계산된다', '불필요한 effect가 보이면 derived state 안티패턴을 의심한다'], Component: Example68, BadCase: BadCase68 },
  { slug: 'anti-patterns/unnecessary-global-state', title: '불필요한 전역 상태', englishTitle: 'Unnecessary Global State', category: '안티패턴', summary: '지역 상태로 충분한 값을 전역 store에 올리는 문제를 피합니다.', whyMatters: '모달 open 여부, 입력 폼 값처럼 한 화면에서만 쓰이는 상태를 Zustand store에 넣으면, store가 비대해지고 컴포넌트 간 의존성이 늘어납니다. 지역 상태는 컴포넌트와 함께 살다 사라져야 합니다.', keyPoints: ['전역 store에 올리기 전에 "다른 화면에서도 쓰나?"를 묻는다', '지역 상태는 컴포넌트가 unmount되면 자동으로 정리된다', 'store가 커질수록 디버깅과 테스트가 어려워진다'], Component: Example69, BadCase: BadCase69 },
  { slug: 'anti-patterns/props-drilling-misunderstanding', title: 'props drilling 오해', englishTitle: 'Props Drilling Misunderstanding', category: '안티패턴', summary: 'props 전달 자체를 문제로 오해해 Context를 남용하는 일을 피합니다.', whyMatters: '2-3단계 props 전달은 자연스럽고 명시적입니다. "drilling이 싫다"는 이유로 모든 곳에 Context를 쓰면 어디서 값이 오는지 추적이 어려워집니다. 진짜 drilling 문제는 5단계 이상, 또는 무관한 컴포넌트를 통해 전달될 때입니다.', keyPoints: ['2-3단계 props 전달은 정상이다', '5단계 이상이거나 완전히 무관한 컴포넌트를 통과할 때 Context를 검토한다', 'Context는 명시적 데이터 흐름을 숨기므로 남용하면 디버깅이 어렵다'], Component: Example70, BadCase: BadCase70 },
  { slug: 'anti-patterns/boolean-props-explosion', title: 'boolean props 폭발', englishTitle: 'Boolean Props Explosion', category: '안티패턴', summary: '여러 boolean prop 조합으로 상태 공간이 커지는 문제를 피합니다.', whyMatters: 'isWarning, isDanger, isSuccess, isLarge, isSmall 같은 boolean이 5개면 2^5=32가지 조합이 생깁니다. 대부분은 의미 없는 조합이고 테스트도 불가능합니다. variant="warning" | "danger"처럼 명시적 열거형으로 유효한 상태만 허용해야 합니다.', keyPoints: ['variant union type으로 유효한 상태만 표현한다', 'boolean은 "켜짐/꺼짐" 독립 개념에만 쓴다(isDisabled, isLoading)', 'boolean 여러 개가 함께 다니면 variant로 통합을 검토한다'], Component: Example71, BadCase: BadCase71 },
  { slug: 'anti-patterns/overuse-memoization', title: '메모이제이션 남용', englishTitle: 'Overuse Memoization', category: '안티패턴', summary: '측정 없이 memo/useMemo/useCallback을 남발하는 문제를 피합니다.', whyMatters: '모든 함수에 useCallback, 모든 값에 useMemo를 쓰면 코드가 복잡해지고 오히려 deps 비교 비용이 생깁니다. React 컴파일러가 없는 환경에서도 "필요한 곳에만 정확히"가 원칙입니다.', keyPoints: ['단순 원시값, 짧은 계산에는 useMemo가 불필요하다', 'useCallback은 memo된 자식에 넘기는 함수에만 쓴다', 'memo는 실제 렌더 비용이 클 때 의미있다'], Component: Example72, BadCase: BadCase72 },
  { slug: 'anti-patterns/index-as-key', title: 'index를 key로 사용', englishTitle: 'Index as Key', category: '안티패턴', summary: '동적 리스트에서 배열 index를 key로 쓰는 문제를 피합니다.', whyMatters: '항목을 추가/삭제/정렬하면 index가 바뀝니다. React는 같은 key를 같은 컴포넌트로 인식하므로, index가 key이면 기존 컴포넌트가 다른 데이터로 재사용됩니다. 입력 중인 텍스트가 다른 행으로 이동하는 버그가 대표적입니다.', keyPoints: ['안정적인 고유 id를 key로 사용한다', '정적이고 순서가 절대 안 바뀌는 목록만 index가 허용된다', 'id가 없으면 crypto.randomUUID()나 nanoid로 생성한다'], Component: Example73, BadCase: BadCase73 },
  { slug: 'anti-patterns/large-component', title: '거대한 컴포넌트', englishTitle: 'Large Component', category: '안티패턴', summary: '하나의 컴포넌트가 데이터, 상태, 표현을 모두 떠안는 문제를 피합니다.', whyMatters: '300줄 이상의 컴포넌트는 어디서 상태가 오고 어디서 이벤트가 발생하는지 추적이 어렵습니다. 변경 이유가 다른 코드들이 한 파일에 있으면 수정 시 무관한 부분까지 영향 범위가 됩니다.', keyPoints: ['단일 책임: 한 컴포넌트는 한 가지 이유로만 바뀌어야 한다', '데이터 로딩과 렌더링을 분리하면 재사용이 쉬워진다', 'custom hook으로 로직을 추출하면 컴포넌트가 가벼워진다'], Component: Example74, BadCase: BadCase74 },
  { slug: 'anti-patterns/api-response-leaking-to-ui', title: 'API 응답 UI 누수', englishTitle: 'API Response Leaking to UI', category: '안티패턴', summary: '서버 응답 구조가 UI 컴포넌트까지 새는 문제를 피합니다.', whyMatters: 'user_name, created_at 같은 서버 snake_case를 컴포넌트 props로 직접 받으면, 서버 API가 바뀔 때 UI 컴포넌트 파일들을 모두 수정해야 합니다. adapter 계층에서 UI 타입으로 변환하면 변경 격리가 됩니다.', keyPoints: ['서버 타입을 직접 컴포넌트 props에 쓰지 않는다', 'adapter/transform 함수로 서버 타입을 UI 타입으로 변환한다', '서버 스키마 변경이 UI 코드에 영향을 주지 않게 된다'], Component: Example75, BadCase: BadCase75 },
  { slug: 'anti-patterns/duplicated-loading-state', title: '중복 로딩 상태', englishTitle: 'Duplicated Loading State', category: '안티패턴', summary: '같은 요청 상태를 여러 boolean으로 중복 관리하는 문제를 피합니다.', whyMatters: 'isLoading, isError, isSuccess를 각각 boolean state로 관리하면 isLoading=false이면서 isError=false이면서 isSuccess=false인 초기 상태, 그리고 isLoading=true이면서 isSuccess=true인 불가능한 상태가 생깁니다.', keyPoints: ["status: 'idle' | 'loading' | 'success' | 'error' 하나로 표현한다", '불가능한 상태 조합이 타입 수준에서 차단된다', 'switch(status)로 렌더 분기가 exhaustive하게 된다'], Component: Example76, BadCase: BadCase76 },
  { slug: 'anti-patterns/mixed-server-client-state', title: '서버/클라이언트 상태 혼합', englishTitle: 'Mixed Server / Client State', category: '안티패턴', summary: '서버 상태와 클라이언트 UI 상태의 소유권을 섞는 문제를 피합니다.', whyMatters: '서버 데이터(users 배열)와 UI 상태(selectedUserId)를 같은 Zustand store에 넣으면, users를 refetch할 때 selectedUserId가 리셋되거나, 반대로 캐시 무효화 로직이 복잡해집니다.', keyPoints: ['서버 상태는 TanStack Query, SWR처럼 캐시를 전담하는 도구에 맡긴다', 'UI 상태(선택, 열림/닫힘)는 local state나 store에서 별도로 관리한다', '두 종류의 상태가 같은 업데이트 주기를 갖는 경우는 드물다'], Component: Example77, BadCase: BadCase77 },
  { slug: 'anti-patterns/inline-object-props', title: '인라인 객체 props', englishTitle: 'Inline Object Props', category: '안티패턴', summary: '매 렌더마다 새 객체 prop을 내려 memoization을 깨는 문제를 피합니다.', whyMatters: '<Child style={{ color: "red" }} />는 매 렌더마다 새 객체가 만들어집니다. Child가 React.memo로 감싸져 있어도 style prop이 항상 바뀌어 memo가 무효화됩니다. 객체는 컴포넌트 밖에 상수로 꺼내거나 useMemo를 써야 합니다.', keyPoints: ['인라인 객체 {}와 배열 []은 매 렌더마다 새 참조다', 'memo 밖에 상수로 꺼내거나 useMemo로 캐시한다', '이벤트 핸들러 인라인 함수도 같은 이유로 주의한다'], Component: Example78, BadCase: BadCase78 },
  { slug: 'anti-patterns/unstable-callbacks', title: '불안정한 콜백', englishTitle: 'Unstable Callbacks', category: '안티패턴', summary: '불안정한 콜백 때문에 하위 컴포넌트 렌더가 퍼지는 문제를 피합니다.', whyMatters: 'memo된 자식에 매 렌더마다 새로 만들어진 함수를 prop으로 내리면 memo가 의미없어집니다. useCallback으로 함수 참조를 안정화해야 자식의 불필요한 리렌더를 막을 수 있습니다.', keyPoints: ['memo된 자식에 넘기는 함수는 useCallback으로 감싼다', '함수가 매 렌더마다 새로 만들어지면 === 비교에서 false다', 'useEffect deps에 넣는 함수도 useCallback이 필요하다'], Component: Example79, BadCase: BadCase79 },
  { slug: 'anti-patterns/effect-cleanup-missing', title: 'effect cleanup 누락', englishTitle: 'Effect Cleanup Missing', category: '안티패턴', summary: '구독, 타이머, 외부 연결을 cleanup하지 않는 문제를 피합니다.', whyMatters: 'setInterval, addEventListener, WebSocket처럼 외부 리소스를 점유하는 코드를 useEffect에서 정리하지 않으면 컴포넌트가 unmount돼도 계속 실행됩니다. 메모리 누수와 setState 경고가 발생합니다.', keyPoints: ['effect return 함수에서 반드시 cleanup한다', 'clearInterval, removeEventListener, ws.close()가 cleanup에 들어간다', 'React StrictMode에서 mount→unmount→mount를 두 번 하므로 cleanup이 빠지면 바로 보인다'], Component: Example80, BadCase: BadCase80 },
];
